/** 
 * Returns a <tt>Map</tt>, containing all [key, value] pairs for image resource pack.
 * @return a <tt>Map</tt>, containing all [key, value] pairs for imageresource pack.
 */
public Map<String,String> getImageResources(){
  if (imageResources != null) {
    return imageResources;
  }
  ResourceBundle resourceBundle=ResourceBundle.getBundle(DEFAULT_IMAGE_RESOURCE_PATH);
  Map<String,String> resources=new TreeMap<String,String>();
  this.initResources(resourceBundle,resources);
  try {
    this.initImagePluginResources(resources);
  } catch (RuntimeException e) {
    // Log the exception and handle it gracefully
    System.err.println("An error occurred while initializing image plugin resources: " + e.getMessage());
    e.printStackTrace();
  }
  imageResources=resources;
  return resources;
}
